from typing import List

class Solution:
    def singleNumber(self, nums: List[int]) -> List[int]:
        ans = []
        for x in nums:
            count = 0
            for y in nums:
                if x == y:
                    count += 1
            if count == 1:
                ans.append(x)
        return ans

