from typing import List

class Solution:
    def singleNumber(self, nums: List[int]) -> List[int]:
        xor_all = 0
        for x in nums:
            xor_all ^= x
        diff_bit = xor_all & -xor_all
        a = 0
        b = 0
        for x in nums:
            if x & diff_bit:
                a ^= x
            else:
                b ^= x
        return [a, b]

